/**
 * Vagabond — Sync Items From Compendium
 * ---------------------------------------------------------------------------
 * Re-pulls the CURRENT compendium version of every compendium-linked item
 * embedded on an actor — world actors AND tokens on the active scene
 * (linked or unlinked). Use after editing compendium content (renames,
 * property changes, description edits, new Active Effects) so copies already
 * on sheets/tokens catch up without deleting and re-dragging them.
 *
 * A copy is "linked" if it carries item._stats.compendiumSource (v12+) or
 * flags.core.sourceId (older). Copies made by hand (no source) are skipped.
 * ---------------------------------------------------------------------------
 * CONFIG
 *   MODE:
 *     "safe" (default) — sync name, img, system, effects BUT keep per-instance
 *                        state (see PRESERVE_SYSTEM). Recommended for live games.
 *     "name"           — sync name + img only. Nothing else touched.
 *     "full"           — overwrite name + img + system + effects wholesale.
 *                        DESTROYS instance state (quantity, equip, grid slot…).
 *   NAME_FILTER: null, or a string treated as a case-insensitive regex — only
 *                items whose current OR source name matches are synced.
 *                e.g. "ace - " or "^Dagger" or "Grapple"
 *   DRY_RUN: true → report what WOULD change, write nothing.
 * ---------------------------------------------------------------------------
 */
(async () => {
  if (!game.user.isGM) return ui.notifications.warn("Sync Items From Compendium: GM only.");

  const MODE = "safe";
  const NAME_FILTER = null;
  const DRY_RUN = false;

  const PRESERVE_SYSTEM = [
    "quantity", "equipmentState", "equipped", "gridPosition", "containerId",
    "uses", "coating", "imbuedSpell", "locked", "bound", "favorite",
    "preparedSpell", "attunement"
  ];

  const rx = NAME_FILTER ? new RegExp(NAME_FILTER, "i") : null;
  const srcCache = new Map();
  const getSource = async (uuid) => {
    if (srcCache.has(uuid)) return srcCache.get(uuid);
    let doc = null;
    try { doc = await fromUuid(uuid); } catch (_) {}
    srcCache.set(uuid, doc);
    return doc;
  };

  // Collect every actor once: world actors + scene token actors (linked + synthetic)
  const actors = new Map();
  for (const a of game.actors) actors.set(a.uuid, a);
  for (const t of canvas?.tokens?.placeables ?? []) if (t.actor) actors.set(t.actor.uuid, t.actor);

  const stats = { actors: 0, scanned: 0, updated: 0, noSource: 0, brokenLink: 0, skippedFilter: 0, errors: 0 };
  const changedNames = [];

  for (const actor of actors.values()) {
    stats.actors++;
    const updates = [];

    for (const item of actor.items) {
      stats.scanned++;
      const srcUuid = item._stats?.compendiumSource || item.flags?.core?.sourceId || null;
      if (!srcUuid || !srcUuid.startsWith("Compendium.")) { stats.noSource++; continue; }

      const src = await getSource(srcUuid);
      if (!src) {
        stats.brokenLink++;
        console.warn(`Sync Items | broken link: "${item.name}" on ${actor.name} → ${srcUuid}`);
        continue;
      }

      if (rx && !rx.test(item.name) && !rx.test(src.name)) { stats.skippedFilter++; continue; }

      const s = src.toObject();
      const upd = { _id: item.id, name: s.name, img: s.img };

      if (MODE === "full") {
        upd.system = s.system;
        upd.effects = s.effects;
      } else if (MODE === "safe") {
        const keep = {};
        for (const k of PRESERVE_SYSTEM)
          if (foundry.utils.hasProperty(item.system, k))
            foundry.utils.setProperty(keep, k, foundry.utils.getProperty(item.system, k));
        upd.system = foundry.utils.mergeObject(s.system, keep, { inplace: false });
        upd.effects = s.effects;
      }

      // Cheap change check — skip no-ops so we do not thrash renders
      const before = JSON.stringify({
        name: item.name, img: item.img,
        system: MODE === "name" ? null : item.system,
        effects: MODE === "name" ? null : item.effects.map(e => e.toObject())
      });
      const after = JSON.stringify({
        name: upd.name, img: upd.img,
        system: MODE === "name" ? null : upd.system,
        effects: MODE === "name" ? null : (upd.effects ?? null)
      });
      if (before === after) continue;

      updates.push(upd);
      if (item.name !== s.name) changedNames.push(`${actor.name}: "${item.name}" → "${s.name}"`);
    }

    if (updates.length && !DRY_RUN) {
      try {
        await actor.updateEmbeddedDocuments("Item", updates);
        stats.updated += updates.length;
      } catch (err) {
        stats.errors++;
        console.error(`Sync Items | update failed on ${actor.name}`, err, updates);
      }
    } else {
      stats.updated += updates.length; // dry-run: count intended
    }
  }

  if (changedNames.length) console.log("Sync Items | renames:\n" + changedNames.join("\n"));
  console.log("Sync Items | done", stats);

  const tag = DRY_RUN ? "[DRY RUN] " : "";
  ui.notifications.info(
    `${tag}Sync Items — ${stats.updated} item(s) ${DRY_RUN ? "would be" : ""} updated across ` +
    `${stats.actors} actors (${stats.scanned} scanned). ` +
    `${stats.brokenLink} broken links, ${stats.noSource} unlinked` +
    (stats.errors ? `, ${stats.errors} errors` : "") + ". See console for detail."
  );
})();
